using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Research Agent – Topic: \"{topic}\"\n");

// --- Tool implementations ---
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    ([Description("The search query to look up on the web")] string query) =>
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        // Simulated search results – replace with a real search API (Bing, Google, etc.)
        return Task.FromResult(new[]
        {
            new { Title = $"Latest Research on {query}", Snippet = $"Recent studies show significant progress in {query}. Experts report breakthroughs in efficiency and scalability that could transform the field within the next decade." },
            new { Title = $"{query} - Industry Overview", Snippet = $"The {query} industry has seen $2.1B in investment this year. Key players include major tech companies and specialized startups focusing on practical applications." },
            new { Title = $"Challenges in {query}", Snippet = $"Despite progress, {query} faces challenges including error rates, cost of infrastructure, and the need for specialized talent. Researchers are actively working on solutions." }
        });
    },
    "search_web",
    "Searches the web for information on a given query and returns relevant results.");

var noteToolSave = AIFunctionFactory.Create(
    ([Description("A concise note summarizing a key finding")] string note) =>
    {
        notebook.Add(note);
        Console.WriteLine($"  📝 Note saved ({notebook.Count} total)");
        return $"Note saved. You now have {notebook.Count} note(s).";
    },
    "save_note",
    "Saves a research note for later use in the summary.");

var noteToolRead = AIFunctionFactory.Create(
    () =>
    {
        return notebook.Count == 0
            ? "No notes saved yet."
            : string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
    },
    "read_notes",
    "Reads all previously saved research notes.");

// --- Build the chat client with tool support ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, noteToolSave, noteToolRead]
};

// --- Agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic using the
        available tools, then produce a well-structured summary.

        Process:
        1. Search the web for relevant information (perform 2-3 searches with different queries).
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, read your notes and produce a final summary.

        Your final response should be a comprehensive summary with sections:
        - Overview
        - Key Findings
        - Challenges
        - Outlook
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);

// --- Notebook helper ---
class Notebook
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;
    public int Count => _notes.Count;
    public void Add(string note) => _notes.Add(note);
}

